my_app/
    src/
        main.rs               <- has: mod garden;
        garden.rs             <- has: pub mod vegetables;
        garden/
            vegetables.rs     <- the body of garden::vegetables

// src/main.rs holds mod garden; and main
// src/garden.rs holds the body of mod garden
mod garden {
    // src/garden/vegetables.rs holds the body of mod vegetables
    pub mod vegetables {
        pub fn count() -> u32 {
            3
        }
    }

    pub fn plant(name: &str) -> String {
        format!("planted {name}")
    }
}

fn main() {
    println!("{}, {} in the garden", garden::plant("carrot"), garden::vegetables::count());
}

// Output:
// planted carrot, 3 in the garden

