exercise.solution:
mod shop {
    pub fn open() -> String {
        String::from("shop is open")
    }

    pub mod fruits {
        pub fn count() -> u32 {
            5
        }
    }
}

fn main() {
    let count = shop::fruits::count();
    println!("{}, {} kinds of fruit", shop::open(), count);
}
